<main class="admin-shell"><?= view('partials/admin_sidebar',['active'=>'registrations']) ?><section class="admin-content"><div class="admin-topbar"><div><span class="eyebrow accent">PARTICIPANT DIRECTORY</span><h1 data-testid="registrations-page-title">Registrations</h1></div><span class="mono" data-testid="registration-count"><?= count($registrations) ?> TOTAL RECORDS</span></div><div class="admin-panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Participant</th><th>Registration</th><th>Event</th><th>Payment</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($registrations as $registration): ?><tr data-testid="registration-table-row"><td><strong><?= esc($registration['participant_name']) ?></strong><span class="table-sub"><?= esc($registration['email']) ?></span></td><td class="mono"><?= esc($registration['registration_id']) ?></td><td><?= esc($registration['event_name']) ?><span class="table-sub"><?= esc($registration['category_name']) ?></span></td><td><?= esc(money($registration['total_amount'])) ?><span class="table-sub"><?= esc(strtoupper($registration['payment_status']??'NONE')) ?></span></td><td><span class="<?= status_class($registration['status']) ?>"><?= esc(strtoupper(str_replace('_',' ',$registration['status']))) ?></span></td><td><div class="row-actions"><a class="table-action" href="<?= base_url('admin/registrations/'.$registration['registration_id']) ?>" data-testid="registration-view-link">View</a><?php if($registration['status']==='pending_payment'&&array_intersect(session('roles')??[],['SUPER_ADMIN','FINANCE'])): ?><form method="post" action="<?= base_url('admin/payments/'.$registration['payment_id'].'/verify') ?>" data-testid="manual-payment-form"><input type="hidden" name="<?= csrf_token() ?>" value="<?= csrf_hash() ?>"><input type="hidden" name="reason" value="Offline/manual verification"><button class="table-action" type="submit" data-testid="manual-payment-verify-button">Mark paid</button></form><?php endif ?></div></td></tr><?php endforeach ?></tbody></table></div></div></section></main>